"use client";

import type { ReactNode } from "react";

export function ConfirmSubmitButton({ message, children }: { message: string; children: ReactNode }) {
  return <button type="submit" onClick={(event) => { if (!window.confirm(message)) event.preventDefault(); }}>{children}</button>;
}

import { cookies, headers } from "next/headers";
import { redirect } from "next/navigation";
import { authPool } from "../../../src/auth/server";
import { ACTIVE_ROLE_COOKIE_NAME, resolveOwnedActiveRole } from "../../../src/application/active-role";
import { PostgresProtectedAccountAdminService } from "../../../src/application/protected-account-admin";
import { ProtectedActorError, resolveProtectedUser } from "../../../src/application/protected-actor";
import { ProvisionProtectedAccountForm } from "./provision-protected-account-form";
import { ProtectedAccountEditor } from "./protected-account-editor";
import { ProtectedStaffOnboardingForm } from "./protected-staff-onboarding-form";
import { PersonAdminPanel } from "./person-admin-panel";

type PageProps = { searchParams: Promise<Record<string, string | string[] | undefined>> };

export default async function ProtectedAccountsAdminPage({ searchParams }: PageProps) {
  if (process.env.ORGANY_RUNTIME !== "db") redirect("/");
  const requestHeaders = await headers();
  let currentUser;
  try { currentUser = await resolveProtectedUser(requestHeaders, authPool); }
  catch (error) { if (error instanceof ProtectedActorError) redirect("/sign-in"); throw error; }
  const activeRole = resolveOwnedActiveRole(currentUser.roles, (await cookies()).get(ACTIVE_ROLE_COOKIE_NAME)?.value);
  if (!currentUser.roles.includes("admin") || activeRole !== "admin") redirect("/");
  const snapshot = await new PostgresProtectedAccountAdminService(authPool).list(requestHeaders);
  const activeAdminCount = snapshot.accounts.filter((account) => account.active && account.roles.includes("admin")).length;
  const peopleResult = await authPool.query(`
    select p.id, p.display_name, p.priest, p.organist
    from catalog_persons p
    where p.active = true and (p.priest = true or p.organist = true)
    order by lower(p.display_name)
  `);
  const staffPeople = peopleResult.rows.map((row) => ({ id: String(row.id), displayName: String(row.display_name), priest: Boolean(row.priest), organist: Boolean(row.organist) }));
  const allPeopleResult = await authPool.query(`select id, display_name, active, priest, organist from catalog_persons order by lower(display_name)`);
  const allPeople = allPeopleResult.rows.map((row) => ({ id: String(row.id), displayName: String(row.display_name), active: Boolean(row.active), priest: Boolean(row.priest), organist: Boolean(row.organist) }));
  const params = await searchParams;
  const message = first(params.message);
  const error = first(params.error);
  return <main className="shell"><section className="card planning-form" aria-label="Protected Account administration">
    <div className="app-header"><div><h1>Manage Accounts</h1></div><a href="/">Back to planning</a></div>
    <p className="field-help">Protected staff use username + password. Church-domain roles remain authoritative only in app_user_roles.</p>
    <section className="detail-panel" aria-label="Add staff account"><h2>Add priest / organist account</h2><ProtectedStaffOnboardingForm people={staffPeople} /></section>
    {message && <p className="saved-summary" role="status">{message}</p>}
    {error && <p className="auth-error" role="alert">{error}</p>}
    <section className="detail-panel" aria-label="Provision protected Account"><h2>Provision future staff Account</h2><ProvisionProtectedAccountForm targets={snapshot.eligibleActors} /></section>
    <section aria-label="Existing protected Accounts"><h2>Existing protected Accounts</h2><div style={{ display: "grid", gap: "1rem" }}>{snapshot.accounts.map((account) => <ProtectedAccountEditor key={account.authUserId} account={account} currentAppUserId={currentUser.id} canDeactivate={!(account.active && account.roles.includes("admin") && activeAdminCount === 1)} />)}</div></section>
    <PersonAdminPanel people={allPeople} />
  </section></main>;
}

function first(value: string | string[] | undefined): string | undefined { return Array.isArray(value) ? value[0] : value; }

"use client";

import { FormEvent, useState } from "react";
import { PersonDeleteButton } from "./person-delete-button";

export type ManagedPerson = {
  id: string;
  displayName: string;
  active: boolean;
  priest: boolean;
  organist: boolean;
};

export function PersonAdminPanel({ people }: { people: ManagedPerson[] }) {
  const [pending, setPending] = useState<string | null>(null);
  const [error, setError] = useState<string>();
  const [newPerson, setNewPerson] = useState({ displayName: "", active: true, priest: true, organist: false });

  async function savePerson(person: Omit<ManagedPerson, "id"> & { id?: string }, pendingKey: string) {
    setPending(pendingKey);
    setError(undefined);
    try {
      const response = await fetch("/api/catalog", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          action: "savePerson",
          input: { person },
          actor: { role: "admin" },
        }),
      });
      const body = await response.json().catch(() => undefined) as
        | { success: true; value: ManagedPerson }
        | { success: false; error: { message?: string } }
        | { error?: { message?: string } }
        | undefined;
      if (!response.ok || !body || !("success" in body) || !body.success) {
        const message = body && "error" in body ? body.error?.message : undefined;
        setError(message ?? "Person could not be saved.");
        return;
      }
      window.location.assign("/admin/accounts?message=Person%20saved.");
    } catch {
      setError("Person could not be saved. Please try again.");
    } finally {
      setPending(null);
    }
  }

  async function submitExisting(event: FormEvent<HTMLFormElement>, person: ManagedPerson) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    await savePerson({
      id: person.id,
      displayName: String(data.get("displayName") ?? ""),
      active: data.has("active"),
      priest: data.has("priest"),
      organist: data.has("organist"),
    }, person.id);
  }

  return <section className="detail-panel" aria-label="Person administration">
    <h2>Persons</h2>
    <p className="field-help">Manage Person identity and Planning eligibility here. Protected Account roles remain separate. Permanent deletion succeeds only when no protected Account or Working, Final, or Completed service references the Person.</p>

    <form className="planning-form person-admin-create" onSubmit={(event) => {
      event.preventDefault();
      void savePerson(newPerson, "new");
    }}>
      <h3>Add Person</h3>
      <label>Display name<input required value={newPerson.displayName} onChange={(event) => setNewPerson((value) => ({ ...value, displayName: event.target.value }))} /></label>
      <div className="form-actions">
        <label><input type="checkbox" checked={newPerson.priest} onChange={(event) => setNewPerson((value) => ({ ...value, priest: event.target.checked }))} /> Priest</label>
        <label><input type="checkbox" checked={newPerson.organist} onChange={(event) => setNewPerson((value) => ({ ...value, organist: event.target.checked }))} /> Organist</label>
        <label><input type="checkbox" checked={newPerson.active} onChange={(event) => setNewPerson((value) => ({ ...value, active: event.target.checked }))} /> Active</label>
      </div>
      <button type="submit" disabled={pending !== null}>{pending === "new" ? "Adding…" : "Add Person"}</button>
    </form>

    {error && <p className="auth-error" role="alert">{error}</p>}

    <div className="person-admin-list">
      {people.map((person) => <article className="detail-panel" key={person.id}>
        <form className="planning-form" onSubmit={(event) => void submitExisting(event, person)}>
          <label>Display name<input name="displayName" defaultValue={person.displayName} required /></label>
          <div className="form-actions">
            <label><input type="checkbox" name="priest" defaultChecked={person.priest} /> Priest</label>
            <label><input type="checkbox" name="organist" defaultChecked={person.organist} /> Organist</label>
            <label><input type="checkbox" name="active" defaultChecked={person.active} /> Active</label>
          </div>
          <div className="form-actions">
            <button type="submit" disabled={pending !== null}>{pending === person.id ? "Saving…" : "Save Person"}</button>
            <PersonDeleteButton personId={person.id} displayName={person.displayName} />
          </div>
        </form>
      </article>)}
    </div>
  </section>;
}

"use client";

import { useState } from "react";

export function PersonDeleteButton({ personId, displayName }: { personId: string; displayName: string }) {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();

  async function deletePerson() {
    if (!window.confirm(`Permanently delete Person ${displayName}? This succeeds only when no account or service history references it.`)) return;
    setPending(true);
    setError(undefined);
    try {
      const response = await fetch("/api/protected-accounts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "deletePerson", personId }),
      });
      const body = await response.json().catch(() => undefined) as { error?: { message?: string } } | undefined;
      if (!response.ok) {
        setError(body?.error?.message ?? "Person was not deleted.");
        return;
      }
      window.location.assign("/admin/accounts?message=Person%20permanently%20deleted.");
    } catch {
      setError("Person was not deleted. Please try again.");
    } finally {
      setPending(false);
    }
  }

  return <div>
    <button type="button" disabled={pending} onClick={deletePerson}>{pending ? "Deleting…" : "Delete Person permanently"}</button>
    {error && <p className="auth-error" role="alert">{error}</p>}
  </div>;
}

import { PasswordVisibilityField } from "../../password-visibility-field";

export function ProvisionProtectedAccountForm({ targets }: { targets: { appUserId: string; displayName: string }[] }) {
  if (targets.length === 0) return <p className="field-help">No eligible Actor is available.</p>;
  return <form action="/api/protected-accounts" method="post" className="planning-form">
    <input type="hidden" name="action" value="provision" />
    <label>Application Actor<select name="appUserId" required>{targets.map((target) => <option key={target.appUserId} value={target.appUserId}>{target.displayName}</option>)}</select></label>
    <label>Username<input name="username" minLength={3} maxLength={64} required /></label>
    <PasswordVisibilityField id="initial-password" label="Initial password" name="password" minLength={8} autoComplete="new-password" required />
    <fieldset><legend>Protected roles</legend><label><input type="checkbox" name="roles" value="admin" /> admin</label><label><input type="checkbox" name="roles" value="priest" /> priest</label><label><input type="checkbox" name="roles" value="organist" defaultChecked /> organist</label></fieldset>
    <button type="submit">Create protected Account</button>
  </form>;
}

import { cookies, headers } from "next/headers";
import { redirect } from "next/navigation";
import { authPool } from "../../../src/auth/server";
import { ACTIVE_ROLE_COOKIE_NAME, resolveOwnedActiveRole } from "../../../src/application/active-role";
import { canReadAuditHistory, listAuditEvents } from "../../../src/application/audit-history";
import { presentAuditEvent, type AuditServiceField, type AuditServiceFieldKey, type AuditStatePresentation } from "../../../src/application/audit-history-view";
import { ProtectedActorError, resolveProtectedUser } from "../../../src/application/protected-actor";

export default async function AuditHistoryPage() {
  if (process.env.ORGANY_RUNTIME !== "db") redirect("/");
  const requestHeaders = await headers();
  let currentUser;
  try { currentUser = await resolveProtectedUser(requestHeaders, authPool); }
  catch (error) { if (error instanceof ProtectedActorError) redirect("/sign-in"); throw error; }
  const activeRole = resolveOwnedActiveRole(currentUser.roles, (await cookies()).get(ACTIVE_ROLE_COOKIE_NAME)?.value);
  if (!canReadAuditHistory(currentUser.roles) || activeRole !== "admin") redirect("/");

  const events = await listAuditEvents(authPool);
  return <main className="shell"><section className="card planning-form audit-history-card" aria-label="Audit history">
    <div className="app-header"><div><h1>Audit history</h1></div><a href="/">Back to planning</a></div>
    <p className="field-help">Successful business changes only. Audit history is append-only and read-only.</p>
    <div className="audit-event-list">
      {events.length === 0 && <p>No audit events recorded yet.</p>}
      {events.map((event) => {
        const view = presentAuditEvent(event);
        return <article className="audit-event" key={event.id}>
          <p className="audit-event-header">
            <strong>{view.objectLabel}</strong>
            <span>{view.action}</span>
            <Separator />
            <span>Actor: {view.actorLabel}</span>
            <Separator />
            <span>{view.occurredAtLabel}</span>
          </p>
          <AuditSectionRule />
          <AuditStateLine label="after" state={view.after} />
          <AuditSectionRule />
          <AuditStateLine label="before" state={view.before} />
        </article>;
      })}
    </div>
  </section></main>;
}

function AuditSectionRule() {
  return <div className="audit-section-rule" aria-hidden="true" />;
}

function AuditStateLine({ label, state }: { label: "before" | "after"; state: AuditStatePresentation }) {
  return <div className="audit-state-line">
    <strong className="audit-state-label">{label}:</strong>
    {state.kind === "service" && <AuditServiceState fields={state.fields} />}
    {state.kind === "generic" && <code className="audit-generic-state">{state.text}</code>}
  </div>;
}

function AuditServiceState({ fields }: { fields: AuditServiceField[] }) {
  const primaryLeft = pickFields(fields, ["dateTime", "antiphon", "topic", "note", "language"]);
  const primaryRight = pickFields(fields, ["priest", "organist"]);
  const rows = fields.find((field) => field.key === "rows");
  const lifecycle = fields.find((field) => field.key === "lifecycle");

  return <div className="audit-service-state">
    <div className="audit-service-primary">
      <div className="audit-service-primary-left">
        <AuditFieldSequence fields={primaryLeft} />
      </div>
      <div className="audit-service-primary-right">
        <AuditFieldSequence fields={primaryRight} />
      </div>
    </div>
    <div className="audit-service-secondary">
      <div>{rows && <AuditField field={rows} />}</div>
      <div className="audit-lifecycle-slot">{lifecycle && <AuditField field={lifecycle} />}</div>
    </div>
  </div>;
}

function pickFields(fields: AuditServiceField[], keys: AuditServiceFieldKey[]) {
  return keys.flatMap((key) => {
    const field = fields.find((candidate) => candidate.key === key);
    return field ? [field] : [];
  });
}

function AuditFieldSequence({ fields }: { fields: AuditServiceField[] }) {
  return <>{fields.map((field, index) => <span className="audit-state-field-group" key={field.key}>
    {index > 0 && <Separator />}
    <AuditField field={field} />
  </span>)}</>;
}

function AuditField({ field }: { field: AuditServiceField }) {
  return <span className={field.tone === "muted" ? "audit-state-muted" : field.tone === "changed" ? "audit-state-changed" : undefined}>
    {field.text}
  </span>;
}

function Separator() {
  return <span className="audit-separator" aria-hidden="true">·</span>;
}

import { NextRequest, NextResponse } from "next/server";
import { ACTIVE_ROLE_COOKIE_NAME, resolveOwnedActiveRole } from "../../../../src/application/active-role";
import { PostgresProtectedWhatsAppPhoneService, ProtectedWhatsAppPhoneError } from "../../../../src/application/protected-whatsapp-phone";
import { ProtectedActorError, resolveProtectedUser } from "../../../../src/application/protected-actor";
import { authPool } from "../../../../src/auth/server";

export async function GET(request: NextRequest) {
  if (process.env.ORGANY_RUNTIME !== "db") return problem("WhatsApp phone settings are available only in DB runtime.", 400);
  try {
    const user = await resolveProtectedUser(request.headers, authPool);
    return NextResponse.json(await new PostgresProtectedWhatsAppPhoneService(authPool).get(user));
  } catch (error) { return handleError(error); }
}

export async function PUT(request: NextRequest) {
  if (process.env.ORGANY_RUNTIME !== "db") return problem("WhatsApp phone settings are available only in DB runtime.", 400);
  try {
    const user = await resolveProtectedUser(request.headers, authPool);
    const body = await request.json().catch(() => undefined) as Record<string, unknown> | undefined;
    if (!body) return problem("JSON body is required.", 400);
    const activeRole = resolveOwnedActiveRole(user.roles, request.cookies.get(ACTIVE_ROLE_COOKIE_NAME)?.value);
    return NextResponse.json(await new PostgresProtectedWhatsAppPhoneService(authPool).save(user, activeRole, body.phone));
  } catch (error) { return handleError(error); }
}

export async function DELETE(request: NextRequest) {
  if (process.env.ORGANY_RUNTIME !== "db") return problem("WhatsApp phone settings are available only in DB runtime.", 400);
  try {
    const user = await resolveProtectedUser(request.headers, authPool);
    const activeRole = resolveOwnedActiveRole(user.roles, request.cookies.get(ACTIVE_ROLE_COOKIE_NAME)?.value);
    return NextResponse.json(await new PostgresProtectedWhatsAppPhoneService(authPool).forget(user, activeRole));
  } catch (error) { return handleError(error); }
}

function handleError(error: unknown) {
  if (error instanceof ProtectedWhatsAppPhoneError) {
    const status = error.code === "invalidInput" ? 400 : error.code === "permissionDenied" ? 403 : 404;
    return problem(error.message, status);
  }
  if (error instanceof ProtectedActorError) {
    return problem(error.message, error.code === "unauthenticated" ? 401 : error.code === "permissionDenied" ? 403 : 400);
  }
  return problem(error instanceof Error ? error.message : "WhatsApp phone settings failed.", 500);
}

function problem(message: string, status: number) {
  return NextResponse.json({ error: { message } }, { status });
}

import { toNextJsHandler } from "better-auth/next-js";
import { assertProtectedAuthConfigured, auth } from "../../../../src/auth/server";

const handler = toNextJsHandler(auth);

export async function GET(request: Request) {
  assertProtectedAuthConfigured();
  return handler.GET(request);
}

export async function POST(request: Request) {
  assertProtectedAuthConfigured();
  return handler.POST(request);
}

import { NextResponse } from "next/server";
import { CatalogService, DrizzleCatalogRepository, type CatalogPerson } from "../../../src/application/catalog";
import type { PlanningRole, ServiceLanguage } from "../../../src/planning-lifecycle";
import * as schema from "../../../src/db/schema";
import { ProtectedActorError, resolveProtectedActor } from "../../../src/application/protected-actor";
import { auditEventValues, humanAuditActor } from "../../../src/application/audit-history";
import { getAppDbPool } from "../../../src/db/app-pool";

type CatalogAction = "getPerson" | "getSong" | "getSongs" | "getPlanningPeople" | "getAdminCatalogSnapshot" | "searchPeople" | "listPeople" | "savePerson" | "searchSongs" | "listSongs" | "setSongActive";
const roles: PlanningRole[] = ["priest", "organist", "admin", "congregationMember"];
const serviceLanguages: ServiceLanguage[] = ["czech", "polish", "mixed"];

export async function POST(request: Request) {
  if (process.env.ORGANY_RUNTIME !== "db") return invalidInput("Catalog DB runtime is not enabled.");
  if (!process.env.DATABASE_URL) return NextResponse.json({ error: { code: "internalError", message: "DATABASE_URL is required." } }, { status: 500 });

  let body: { action?: CatalogAction; input?: unknown; actor?: unknown };
  try { body = (await request.json()) as typeof body; } catch { return NextResponse.json({ error: { code: "invalidInput", message: "Malformed JSON body." } }, { status: 400 }); }
  const action = body.action;
  if (!action || !["getPerson", "getSong", "getSongs", "getPlanningPeople", "getAdminCatalogSnapshot", "searchPeople", "listPeople", "savePerson", "searchSongs", "listSongs", "setSongActive"].includes(action)) return invalidInput("Unsupported catalog action.");
  const validationError = validateActionInput(action, body.input);
  if (validationError) return invalidInput(validationError);

  const { drizzle } = await import("drizzle-orm/node-postgres");
  const pool = getAppDbPool();
  try {
    const actor = await resolveProtectedActor(request.headers, pool, body.actor);
    const db = drizzle(pool, { schema });
    let input = body.input as Record<string, unknown>;
    if (action === "savePerson" || action === "setSongActive") input = { ...input, role: actor.role };
    if (action === "savePerson" || action === "setSongActive") {
      const result = await db.transaction(async (tx) => {
        const repo = new DrizzleCatalogRepository(tx);
        const service = new CatalogService(repo);
        const before = action === "savePerson"
          ? (isRecord(input.person) && typeof input.person.id === "string" ? await repo.findPersonById(input.person.id) : undefined)
          : await repo.findSongById(String(input.songId));
        const mutation = await service[action](input as never);
        if (mutation.success) {
          await tx.insert(schema.auditEvents).values(auditEventValues({
            actor: humanAuditActor(actor),
            action: action === "savePerson" ? "catalog.person.save" : "catalog.song.setActive",
            objectKind: action === "savePerson" ? "person" : "song",
            objectRef: action === "savePerson" ? (mutation.value as { id: string }).id : (mutation.value as { songId: string }).songId,
            beforeState: before ?? null,
            afterState: mutation.value,
          }));
        }
        return mutation;
      });
      return NextResponse.json(result);
    }
    const service = new CatalogService(new DrizzleCatalogRepository(db));
    if (action === "getPlanningPeople") {
      const [priests, organists] = await Promise.all([
        service.searchPeople({ role: "priest", query: "" }),
        service.searchPeople({ role: "organist", query: "" }),
      ]);
      if (!priests.success) return NextResponse.json(priests);
      if (!organists.success) return NextResponse.json(organists);
      return NextResponse.json({ success: true, value: { priests: priests.value, organists: organists.value } });
    }
    if (action === "getAdminCatalogSnapshot") {
      if (actor.role !== "admin") return NextResponse.json({ success: false, error: { code: "permissionDenied", message: "Only admin can load the management catalog." } });
      const [people, songs] = await Promise.all([service.listPeople(), service.listSongs()]);
      if (!people.success) return NextResponse.json(people);
      if (!songs.success) return NextResponse.json(songs);
      return NextResponse.json({ success: true, value: { people: people.value, songs: songs.value } });
    }
    return NextResponse.json(await service[action](input as never));
  } catch (error) {
    if (error instanceof ProtectedActorError) return protectedActorFailure(error);
    return NextResponse.json({ error: { code: "internalError", message: error instanceof Error ? error.message : "Catalog API failed." } }, { status: 500 });
  }
}

function validateActionInput(action: CatalogAction, input: unknown): string | undefined {
  if (action === "listPeople" || action === "listSongs" || action === "getPlanningPeople" || action === "getAdminCatalogSnapshot") return undefined;
  if (!isRecord(input)) return "Input object is required.";
  if (action === "getPerson") return typeof input.id === "string" && input.id.trim() ? undefined : "Non-empty person ID is required.";
  if (action === "getSong") return typeof input.songId === "string" && input.songId.trim() ? undefined : "Non-empty song ID is required.";
  if (action === "getSongs") return Array.isArray(input.songIds) && input.songIds.length <= 100 && input.songIds.every((id) => typeof id === "string" && id.trim()) ? undefined : "songIds must be an array of at most 100 non-empty IDs.";
  if (action === "searchPeople") {
    if (input.role !== "priest" && input.role !== "organist") return "Valid person lookup role is required.";
    if (input.query !== undefined && typeof input.query !== "string") return "Lookup query must be a string when provided.";
    return undefined;
  }
  if (action === "searchSongs") {
    if (!serviceLanguages.includes(input.language as ServiceLanguage)) return "Valid service language is required.";
    if (input.query !== undefined && typeof input.query !== "string") return "Lookup query must be a string when provided.";
    return undefined;
  }
  if (action === "setSongActive") {
    if (typeof input.songId !== "string" || !input.songId.trim()) return "songId is required.";
    if (typeof input.active !== "boolean") return "active boolean is required.";
    return undefined;
  }
  if (action === "savePerson") {
    const person = input.person;
    if (!isRecord(person)) return "Malformed person payload.";
    if ("id" in person && person.id !== undefined && (typeof person.id !== "string" || !person.id.trim())) return "Person id must be a non-empty string when provided.";
    if (typeof person.displayName !== "string") return "Person displayName is required.";
    for (const key of ["active", "priest", "organist"] satisfies (keyof CatalogPerson)[]) if (typeof person[key] !== "boolean") return `Person ${key} boolean is required.`;
  }
  return undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> { return typeof value === "object" && value !== null; }
function invalidInput(message: string) { return NextResponse.json({ error: { code: "invalidInput", message } }, { status: 400 }); }
function protectedActorFailure(error: ProtectedActorError) {
  const status = error.code === "unauthenticated" ? 401 : error.code === "invalidInput" ? 400 : 403;
  return NextResponse.json({ error: { code: error.code, message: error.message } }, { status });
}

import { NextRequest, NextResponse } from "next/server";
import { getAppDbPool } from "../../../src/db/app-pool";
import { CongregationVoterError, PostgresCongregationPreferenceService } from "../../../src/application/congregation-preference-voter";

const congregationVoterCookie = "organy_congregation_voter";
type FormAction = "enterNickname" | "saveOwnPreference" | "clearNickname";

export async function POST(request: NextRequest) {
  if (process.env.ORGANY_RUNTIME !== "db") return problem("Congregation preference DB runtime is not enabled.", 400);
  if (!process.env.DATABASE_URL) return problem("DATABASE_URL is required for congregation preferences.", 500);

  const form = await request.formData().catch(() => undefined);
  if (!form) return problem("Form data is required.", 400);
  const action = String(form.get("action") ?? "") as FormAction;

  if (action === "clearNickname") {
    const response = NextResponse.redirect(new URL("/congregation-preferences", request.url), 303);
    response.cookies.delete(congregationVoterCookie);
    return response;
  }

  const pool = getAppDbPool();
  try {
    const service = new PostgresCongregationPreferenceService(pool);
    if (action === "enterNickname") {
      const session = await service.enterNickname(form.get("nickname"));
      const response = NextResponse.redirect(new URL("/congregation-preferences", request.url), 303);
      response.cookies.set(congregationVoterCookie, session.token, {
        httpOnly: true,
        sameSite: "lax",
        secure: process.env.NODE_ENV === "production",
        path: "/",
      });
      return response;
    }

    if (action === "saveOwnPreference") {
      const scoreText = String(form.get("score") ?? "");
      const score = scoreText === "0" ? 0 : scoreText === "1" ? 1 : Number.NaN;
      const songId = String(form.get("referenceSongId") ?? "");
      await service.saveOwnReferencePreference(request.cookies.get(congregationVoterCookie)?.value, songId, score);
      const target = new URL("/congregation-preferences", request.url);
      target.searchParams.set("song", songId);
      target.searchParams.set("saved", "1");
      return NextResponse.redirect(target, 303);
    }

    return problem("Unsupported congregation preference action.", 400);
  } catch (error) {
    if (error instanceof CongregationVoterError) {
      const status = error.code === "invalidInput" ? 400 : error.code === "unauthenticated" ? 401 : error.code === "notFound" ? 404 : 403;
      return problem(error.message, status);
    }
    return problem(error instanceof Error ? error.message : "Congregation preference request failed.", 500);
  }
}

function problem(message: string, status: number) {
  return NextResponse.json({ error: { message } }, { status });
}

